import{_ as e,o as l,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Performance Meeting 2023-07-03","description":"","frontmatter":{"title":"Ceph Performance Meeting 2023-07-03","date":"2023-07-03T00:00:00.000Z","updated":"2023-07-04T00:00:00.000Z","tags":["Ceph","RocksDB","Snappy库","RBD性能","Elastic Shared Blobs"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Performance_Meeting_2023-07-03.md","filePath":"posts/2023/Ceph_Performance_Meeting_2023-07-03.md","lastUpdated":1780459816000}'),r={name:"posts/2023/Ceph_Performance_Meeting_2023-07-03.md"};function o(n,a,s,p,h,c){return l(),i("div",null,[...a[0]||(a[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议时间" tabindex="-1">会议时间 <a class="header-anchor" href="#会议时间" aria-label="Permalink to &quot;会议时间&quot;">​</a></h4><ul><li>日期：2023年7月3日</li><li>参与者：Igor, Casey, Adam, Corey Snyder, Paul等</li></ul><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>GCC 13修复与RocksDB更新</strong></p><ul><li>讨论了GCC 13的修复问题，特别是针对RocksDB的FTBFS问题。</li><li>决定将修复合并到Reef分支，并确保未来更新Main分支时能同步这些更改。</li><li>讨论了RocksDB的版本管理和更新策略，建议定期跟进RocksDB的主要版本更新。</li></ul></li><li><p><strong>Snappy库的问题与替代方案</strong></p><ul><li>讨论了Snappy库在新的操作系统发行版中导致的编译问题，特别是与RTTI支持的缺失有关。</li><li>提出了几种解决方案，包括使用自定义的Snappy分支、禁用系统Snappy库等。</li><li>讨论了Snappy的性能和替代方案，建议考虑弃用Snappy，特别是在RGW中的使用。</li></ul></li><li><p><strong>Elastic Shared Blobs PR的讨论</strong></p><ul><li>讨论了关于Elastic Shared Blobs的PR，特别是关于如何处理部分代码的ifdefs问题。</li><li>决定暂不合并PR，而是先进行必要的修改以适应新的运行时条件。</li></ul></li><li><p><strong>RBD性能测试结果分析</strong></p><ul><li>讨论了RBD在Reef和Quincy版本中的性能测试结果，特别是关于CPU使用率和I/O效率的问题。</li><li>提出了一些假设和测试方向，包括调整内存目标大小、不同I/O大小的测试等。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>确认了RocksDB的更新策略，建议定期跟进主要版本更新。</li><li>对于Snappy库的问题，决定先观察其他发行版的处理方式，再决定具体实施方案。</li><li>Elastic Shared Blobs PR将进行必要的修改后再考虑合并。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续监控和分析RBD性能测试结果，特别是关于RocksDB和I/O效率的问题。</li><li>跟进Snappy库的问题，特别是与其他发行版的协调和处理方式。</li><li>修改并重新审查Elastic Shared Blobs PR，确保其符合新的运行时条件后进行合并。</li></ul><h4 id="其他讨论" tabindex="-1">其他讨论 <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论&quot;">​</a></h4><ul><li>讨论了Debian和Fedora对于Snappy库的处理方式，建议在主问题跟踪器中记录相关问题。</li><li>讨论了RBD性能测试中的具体细节和可能的优化方向。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><ul><li>会议在讨论完所有议题后结束，感谢所有参与者的贡献，并祝愿大家有一个愉快的一周。</li></ul>',13)])])}const _=e(r,[["render",o]]);export{u as __pageData,_ as default};
